#include <iostream>

int main() {
    int x = 0;
    if (std::cin >> x) {
        // Single-entry: sequence enters here
        // Selection: single entry point, evaluates condition
        if (x > 0) {
            std::cout << "Positive\n";
        } else if (x < 0) {
            std::cout << "Negative\n";
        } else {
            std::cout << "Zero\n";
        }
        // Single-exit: all branches converge here
    }
    return 0;
}

#include <iostream>

int main() {
    // Stacked action 1: Input
    int count = 0;
    if (std::cin >> count) {
        // Stacked action 2: Nested control structure (for loop containing if-else)
        for (int i = 1; i <= count; ++i) {
            // Rule 3 (Nesting): Action replaced with double-selection
            if (i % 2 == 0) {
                std::cout << i << ": even\n";
            } else {
                std::cout << i << ": odd\n";
            }
        }
    }
    return 0;
}
